function stepImpl(input, ctx) {
  const eff = [];
  let st = ctx.state;
  switch (input.op) {
    case 'start':
      st = fresh(input);
      eff.push(sv(st, 'processing', 'fs-processing'));
      advance(st, ctx, eff);
